#define assert(x) ((void)0)
#define INT_MAX 2147483647
#define UNINITIALIZED_WEDGE_REF 0xffff

struct string_buf {
  unsigned long long *data;
  int ref_count, char_length, block_length, max_blocks;
};

class stringx {
  friend stringx operator+(const stringx &, const stringx &);
protected:
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx &);
  stringx(const char *, int = -1);
  ~stringx();
  void append(const stringx &);
  void make_room(int);
  const char *c_str() const { return chars; }
};

inline stringx operator+(const stringx &lhs, const stringx &rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

class chunk_flavor {
  char flavor[16];
public:
  chunk_flavor(const char *text) { strcpy(flavor, text); }
  bool operator==(const chunk_flavor &) const;
  stringx to_stringx() const;
};

class chunk_file {
public:
  stringx get_name();
};

typedef unsigned short wedge_ref;
typedef unsigned short vert_ref;

class wedge {
public:
  short level_of_detail;
  wedge_ref lower_detail;
};

struct texture_coord {
  float x, y;
};

struct vector3d {
  float x, y, z;
};

struct color {
  float r, g, b, a;
};

extern chunk_flavor CHUNK_TEXTURE_COORD;
extern chunk_flavor CHUNK_NORMAL;
extern chunk_flavor CHUNK_COLOR;
extern chunk_flavor CHUNK_END;

void serial_in(chunk_file &, unsigned short *);
void serial_in(chunk_file &, int *);
void serial_in(chunk_file &, float *);
void serial_in(chunk_file &, chunk_flavor *);

inline void serial_in(chunk_file &io, texture_coord *tc)
{
  serial_in(io, &tc->x);
  serial_in(io, &tc->y);
}

inline void serial_in(chunk_file &io, vector3d *v)
{
  serial_in(io, &v->x);
  serial_in(io, &v->y);
  serial_in(io, &v->z);
}

inline void serial_in(chunk_file &io, color *c)
{
  serial_in(io, &c->r);
  serial_in(io, &c->g);
  serial_in(io, &c->b);
  serial_in(io, &c->a);
}

